-- Explicit operator judgments; preserve source observations and stable identifiers.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
lock table machimoa_review.source_item_program_facts,machimoa_review.source_item_content_filters,machimoa_review.review_classifications,machimoa_review.review_classification_history in share row exclusive mode;
do $$ begin
if to_regprocedure('machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'3bbb9fe2157161cd1ac6c33e25685e24323c2504524237c1fbdd93b9c33ccfef' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)';end if;
if to_regprocedure('machimoa_review.classification_reasons(uuid, jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.classification_reasons(uuid, jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'e481b55ef165d3a135e2e7a9d0a7ed674c1f72282be3ad6eeb0916f6b16ed250' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.classification_reasons(uuid, jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','machimoa_review.classification_reasons(uuid, jsonb)';end if;
if to_regprocedure('public.admin_myseoul_program_detail(uuid)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('public.admin_myseoul_program_detail(uuid)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'3a8fe9f449e639c220c1297f73a3a1ac0b1fd292431fb01c85c0c30a77226ead' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('public.admin_myseoul_program_detail(uuid)')) is distinct from '{"acl": ["postgres=X/postgres", "service_role=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": true}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','public.admin_myseoul_program_detail(uuid)';end if;
if to_regprocedure('machimoa_review.myseoul_reason_fields(text)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_reason_fields(text)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'56c1b0b3e618ff77e566bfbc0081684d4fd2b8bc60619122fd9b1b4d0358f667' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_reason_fields(text)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','machimoa_review.myseoul_reason_fields(text)';end if;
if to_regprocedure('public.admin_myseoul_program_save_v2(uuid, text, text, jsonb, uuid)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('public.admin_myseoul_program_save_v2(uuid, text, text, jsonb, uuid)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'6893a3debf5321edf8426fc06b27a8c61a1419e0e7fcea87e289714e82409835' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('public.admin_myseoul_program_save_v2(uuid, text, text, jsonb, uuid)')) is distinct from '{"acl": ["postgres=X/postgres", "service_role=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": true}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','public.admin_myseoul_program_save_v2(uuid, text, text, jsonb, uuid)';end if;
if to_regprocedure('machimoa_review.myseoul_admin_lock(uuid, text, text, uuid)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_admin_lock(uuid, text, text, uuid)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'1432dbe8a4453ff0fd9cd3aef982011216870f50f6831e1d81a2b5c3322a7353' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_admin_lock(uuid, text, text, uuid)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','machimoa_review.myseoul_admin_lock(uuid, text, text, uuid)';end if;
if to_regprocedure('machimoa_review.myseoul_ai_preparation_check(uuid, text, bigint)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_ai_preparation_check(uuid, text, bigint)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'4bb1b878e20fcb56c888912f65b86209fdb2a0fbee912e9930e5d38e7590c98e' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_ai_preparation_check(uuid, text, bigint)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": true}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','machimoa_review.myseoul_ai_preparation_check(uuid, text, bigint)';end if;
if to_regprocedure('public.admin_review_reclassify(uuid, text, text, bigint, jsonb, jsonb, text, uuid)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('public.admin_review_reclassify(uuid, text, text, bigint, jsonb, jsonb, text, uuid)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'84a635a680140c0999528d01d9a413e05cd85ca92e05156ddb8887ab064ec10b' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('public.admin_review_reclassify(uuid, text, text, bigint, jsonb, jsonb, text, uuid)')) is distinct from '{"acl": ["postgres=X/postgres", "service_role=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": true}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','public.admin_review_reclassify(uuid, text, text, bigint, jsonb, jsonb, text, uuid)';end if;
if to_regprocedure('public.claim_reclassified_content_ai(uuid, text, bigint, text, integer)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('public.claim_reclassified_content_ai(uuid, text, bigint, text, integer)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'ce54aa3ed8653e51fbc1b22a662c85594fcbb2e02f717ba8f4ab0fd43712dd90' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('public.claim_reclassified_content_ai(uuid, text, bigint, text, integer)')) is distinct from '{"acl": ["postgres=X/postgres", "service_role=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": true}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','public.claim_reclassified_content_ai(uuid, text, bigint, text, integer)';end if;
if to_regprocedure('machimoa_review.content_filter_consistent(uuid, text, jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.content_filter_consistent(uuid, text, jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'e3ef7e5965540aad282a3bb95c4a6f3e059d50f839f96b30b1823099317667e7' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.content_filter_consistent(uuid, text, jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_predecessor_changed: %','machimoa_review.content_filter_consistent(uuid, text, jsonb)';end if;
if to_regclass('machimoa_review.myseoul_confirmation_install') is not null then raise exception 'myseoul_confirmation_already_installed';end if;
end $$;
create table machimoa_review.myseoul_confirmation_install(singleton boolean primary key check(singleton),dirty boolean not null default false,backup jsonb not null);
alter table machimoa_review.myseoul_confirmation_install enable row level security;
revoke all on machimoa_review.myseoul_confirmation_install from public,anon,authenticated,service_role;
insert into machimoa_review.myseoul_confirmation_install values(true,false,'{"machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)": "CREATE OR REPLACE FUNCTION machimoa_review.myseoul_evaluate(f jsonb, p_now timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare reasons text[]:=array(select value->>''code'' from jsonb_array_elements(f->''issues''));\n exclusions text[]:=array(select jsonb_array_elements_text(f->''scope_exclusions'')); app text:=''unknown''; mode text:=f->>''delivery_mode'';\n k text; p jsonb; app_period jsonb; op_period jsonb; endpoint jsonb; boundary timestamptz; decision text; quality text; scope text; status text;\nbegin\n perform machimoa_review.myseoul_validate(f);\n if p_now is null then raise exception using errcode=''PT422'',message=''evaluation_time_required'';end if;\n if f->>''application_actor''=''institution_only'' then exclusions:=array_append(exclusions,''institution_only'');end if;\n if char_length(btrim(f->>''description''))<20 then reasons:=array_append(reasons,''description_missing'');end if;\n if btrim(f->>''target'')='''' then reasons:=array_append(reasons,''target_missing'');end if;\n if f->>''application_actor''=''unknown'' then reasons:=array_append(reasons,''application_actor_unknown'');end if;\n if f->>''public_category''=''unknown'' then reasons:=array_append(reasons,''category_unresolved'');end if;\n if mode in (''unknown'',''course_unresolved'') then reasons:=array_append(reasons,case when mode=''unknown'' then ''delivery_mode_unknown'' else ''course_modes_unresolved'' end);end if;\n if mode in (''offline'',''mixed'') then\n if f->>''activity_region''=''noncapital'' then exclusions:=array_append(exclusions,''noncapital_venue'');\n elsif f->>''activity_region''<>''capital'' or (f->''activity_evidence''=''[]''::jsonb and not machimoa_review.myseoul_activity_confirmed(f)) or btrim(f->>''venue'')='''' then reasons:=array_append(reasons,''activity_region_unknown'');end if;end if;\n if mode=''online'' then\n if f->>''residence_scope''=''noncapital_only'' then exclusions:=array_append(exclusions,''online_noncapital_only'');\n elsif (f->>''residence_scope'' not in (''nationwide'',''includes_capital'',''capital'') or f->''residence_evidence''=''[]''::jsonb) and not machimoa_review.myseoul_residence_confirmed(f) then reasons:=array_append(reasons,''online_residence_unknown'');end if;end if;\n if f->''application_methods''=''[]''::jsonb then reasons:=array_append(reasons,''application_method_missing'');end if;\n if f->''fees''=''[]''::jsonb or exists(select 1 from jsonb_array_elements(f->''fees'') fee cross join lateral jsonb_array_elements_text(fee->''evidence'') v\n where v !~ ''\ubb34\ub8cc|[0-9][0-9,]*[[:space:]]*\uc6d0|\ubcc4\ub3c4[[:space:]]*(\ubd80\ub2f4|\ub0a9\ubd80)'') then reasons:=array_append(reasons,''fee_unknown'');end if;\n for k in select fee->>''component'' from jsonb_array_elements(f->''fees'') fee cross join lateral jsonb_array_elements_text(fee->''evidence'') v\n group by fee->>''component'' having count(distinct machimoa_review.myseoul_comparison(fee->>''component'',v))>1 loop\n reasons:=array_append(reasons,''source_fact_conflict:''||k);end loop;\n foreach k in array array[''application'',''operation''] loop\n if exists(select 1 from jsonb_array_elements(f->''periods''->k) v where v->>''status''<>''ok'') or k=''operation'' and not exists(\n select 1 from jsonb_array_elements(f->''periods''->k) v where v->>''status''=''ok'') then reasons:=array_append(reasons,k||''_period_unknown'');end if;\n if (select count(distinct v->''endpoints'') from jsonb_array_elements(f->''periods''->k) v where v->>''status''=''ok'')>1 then reasons:=array_append(reasons,''source_fact_conflict:''||k);end if;end loop;\n if (select count(distinct machimoa_review.myseoul_comparison(''status'',v)) from jsonb_array_elements_text(f->''source_status'') v)>1 then reasons:=array_append(reasons,''source_fact_conflict:status'');end if;\n select value into app_period from jsonb_array_elements(f->''periods''->''application'') where value->>''status''=''ok'' limit 1;\n select value into op_period from jsonb_array_elements(f->''periods''->''operation'') where value->>''status''=''ok'' limit 1;\n status:=array_to_string(array(select jsonb_array_elements_text(f->''source_status'')),E''\\n'');\n if status ~ ''\uc811\uc218[[:space:]]*\uc885\ub8cc|\ubaa8\uc9d1[[:space:]]*\uc885\ub8cc|\uc608\uc57d[[:space:]]*\ub9c8\uac10|\uc811\uc218[[:space:]]*\ub9c8\uac10|\uc2e0\uccad[[:space:]]*(\ub9c8\uac10|\uc885\ub8cc)'' then app:=''closed'';\n elsif app_period is not null then\n endpoint:=app_period->''endpoints''->(jsonb_array_length(app_period->''endpoints'')-1);\n boundary:=machimoa_review.myseoul_boundary(endpoint,true);\n app:=case when p_now<machimoa_review.myseoul_boundary(app_period->''endpoints''->0,false) then ''not_started''\n when endpoint->>''precision''=''day'' and p_now>=boundary or endpoint->>''precision''=''minute'' and p_now>boundary then ''closed'' else ''open'' end;\n elsif status ~ ''\uc811\uc218[[:space:]]*\uc911|\ubaa8\uc9d1[[:space:]]*\uc911|\uc2e0\uccad[[:space:]]*\uc911|\ucd94\uac00[[:space:]]*\ubaa8\uc9d1|\ud604\uc7a5[[:space:]]*\uc811\uc218'' then app:=''open'';\n else reasons:=array_append(reasons,''application_period_unknown'');end if;\n if op_period is not null then endpoint:=op_period->''endpoints''->(jsonb_array_length(op_period->''endpoints'')-1);\n boundary:=machimoa_review.myseoul_boundary(endpoint,true);\n if endpoint->>''precision''=''day'' and p_now>=boundary or endpoint->>''precision''=''minute'' and p_now>boundary then app:=''ended'';end if;end if;\n if reasons && array[''source_fact_conflict:application'',''source_fact_conflict:operation'',''source_fact_conflict:status''] then app:=''unknown'';end if;\n if app=''unknown'' then reasons:=array_append(reasons,''application_state_unknown'');end if;\n select coalesce(array_agg(code order by ord),''{}'') into reasons from (select code,min(ord) ord from unnest(reasons) with ordinality q(code,ord) group by code) q;\n select coalesce(array_agg(code order by ord),''{}'') into exclusions from (select code,min(ord) ord from unnest(exclusions) with ordinality q(code,ord) group by code) q;\n scope:=case when cardinality(exclusions)>0 then ''excluded'' when reasons && array[''target_missing'',''application_actor_unknown'',''delivery_mode_unknown'',\n ''course_modes_unresolved'',''activity_region_unknown'',''online_residence_unknown'',''category_unresolved'',''nationality_or_visa_unresolved''] then ''unknown'' else ''included'' end;\n quality:=case when exists(select 1 from unnest(reasons) r where r like ''source_fact_conflict:%'' or r like ''source_change_conflict:%'') then ''conflict'' when cardinality(reasons)>0 then ''insufficient'' else ''sufficient'' end;\n decision:=case when cardinality(exclusions)>0 then ''out_of_scope'' when cardinality(reasons)>0 then ''review_required'' when app=''open'' then ''in_scope'' else ''not_currently_available'' end;\n reasons:=exclusions||reasons;\n if app in (''closed'',''not_started'',''ended'') then reasons:=array_append(reasons,case when app=''ended'' then ''operation_ended'' else ''application_''||app end);end if;\n select coalesce(array_agg(code order by ord),''{}'') into reasons from (select code,min(ord) ord from unnest(reasons) with ordinality q(code,ord) group by code) q;\n return jsonb_build_object(''decision'',decision,''disposition'',case when cardinality(exclusions)>0 then ''non_target'' when decision=''in_scope'' then ''target'' else ''observe_only'' end,\n ''scope'',scope,''application'',app,''quality'',quality,''public_category'',f->>''public_category'',''reasons'',to_jsonb(reasons),''ai_status'',''blocked'');\nend $function$\n", "machimoa_review.classification_reasons(uuid, jsonb)": "CREATE OR REPLACE FUNCTION machimoa_review.classification_reasons(p_id uuid, f jsonb)\n RETURNS text[]\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''''\nAS $function$\ndeclare s machimoa_review.source_items%rowtype;pf machimoa_review.source_item_program_facts%rowtype;r jsonb;codes text[];g jsonb;d jsonb;venue_mode boolean;venue_ready boolean:=false;\nbegin\n select * into s from machimoa_review.source_items where id=p_id;\n select * into pf from machimoa_review.source_item_program_facts where source_item_id=p_id and revision_hash=s.revision_hash;\n if pf.source_item_id is not null then\n r:=case when s.source_id=''myseoul_program'' then machimoa_review.myseoul_evaluate(pf.facts,statement_timestamp()) else machimoa_review.program_evaluate(pf.facts,statement_timestamp()) end;\n if pf.manual_excluded or r->>''decision''=''out_of_scope'' then return array[''classification_source_excluded''];end if;\n select array(select code from jsonb_array_elements_text(coalesce(r->''reasons'',''[]'')) code where not (machimoa_review.publication_temporal_ready(r) and code in (''application_not_started'',''application_closed'',''operation_ended'',''not_currently_accepting'',''program_ended'')) and code not in\n (''category_unresolved'',''delivery_mode_unknown'',''activity_region_unknown'',''application_period_unknown'',''operation_period_unknown'',''application_state_unknown'',''online_residence_unknown'') and code not like ''content_filter:%'') into codes;\n else codes:=''{}'';end if;\n if f->>''productType'' not in (''event_program'',''policy_reference'',''living_guide'') then return array_append(codes,''classification_missing_facts'');end if;\n select to_jsonb(gate) into g from machimoa_review.evaluate_source_item_gates(s.body_usable,s.has_source_url,s.attachment_present,f->>''productType'',''{}'',machimoa_review.classification_gate(f)) gate;\n select filters into d from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=s.revision_hash;\n if (d is null or d->>''category'' is distinct from f->>''category'') and f->>''category'' in (''program'',''event'',''youth_space'') then d:=machimoa_review.classification_draft(p_id,f->>''category'')->''filters'';end if;\n venue_mode:=f->>''productType''=''event_program'' and f->>''category'' in (''program'',''event'',''youth_space'') and f->>''delivery'' in (''offline'',''hybrid'') and (f->>''category''<>''youth_space'' or d->''spaceKind''->>''value'' is distinct from ''news'');\n if venue_mode then\n select filters into d from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=s.revision_hash;\n if d is null or d->>''category'' is distinct from f->>''category'' then d:=machimoa_review.classification_draft(p_id,f->>''category'')->''filters'';end if;\n venue_ready:=d->''location''->>''status''=''known'' and (d->''location''->''value''->>''scope''=''nationwide'' or d->''location''->''value''->>''scope''=''specific'' and jsonb_array_length(d->''location''->''value''->''venues'')>0 and not exists(select 1 from jsonb_array_elements(d->''location''->''value''->''venues'') x where x->>''province'' not in (''11'',''28'',''41'')));\n if coalesce(venue_ready,false) is not true then codes:=array_append(codes,''activity_region_unknown'');end if;\n end if;\n codes:=codes||array(select code from jsonb_array_elements(coalesce(g->''jobs'',''[]'')) job cross join lateral jsonb_array_elements_text(job->''reason_codes'') code where not (venue_mode and coalesce(venue_ready,false) and code=''region_scope_unknown''));\n if g->>''disposition''<>''target'' and cardinality(codes)=0 and not (venue_mode and coalesce(venue_ready,false) and g->>''disposition''=''region_review_required'' and g->>''region_status''=''review_required'' and g->>''audience_status''=''not_applicable'') then codes:=array_append(codes,''classification_scope_unresolved'');end if;\n return array(select distinct c from unnest(codes) c);\nend $function$\n", "public.admin_myseoul_program_detail(uuid)": "CREATE OR REPLACE FUNCTION public.admin_myseoul_program_detail(p_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare item jsonb;c machimoa_review.review_classifications%rowtype;codes text[];begin item:=machimoa_review.cl_base_pub_admin_myseoul_program_detail(p_id);select * into c from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=item->>''revision'';if not found then return item||jsonb_build_object(''residenceReview'',jsonb_build_object(''confirmed'',not (item->''result''->''reasons'') ? ''online_residence_unknown'' and item->''facts''->>''delivery_mode''=''online'' and (machimoa_review.myseoul_residence_confirmed(item->''facts'') or item->''facts''->>''residence_scope'' in (''nationwide'',''includes_capital'',''capital'') and item->''facts''->''residence_evidence''<>''[]''::jsonb), ''basis'',case when machimoa_review.myseoul_residence_confirmed(item->''facts'') then ''operator_no_restriction'' when item->''facts''->>''residence_scope'' in (''nationwide'',''includes_capital'',''capital'') and item->''facts''->''residence_evidence''<>''[]''::jsonb then ''source_evidence'' else ''unconfirmed'' end));end if;codes:=array(select distinct code from unnest(machimoa_review.classification_reasons(p_id,c.facts)||array(select unnest(j.reason_codes) from machimoa_review.processing_jobs j where j.source_item_id=p_id and j.revision_hash=c.revision_hash and j.processing_stage<>''ai_enrichment'' and j.status in (''queued'',''claimed''))) code);if c.native_snapshot is distinct from machimoa_review.classification_native(p_id) then codes:=array_append(codes,''classification_input_changed'');end if;item:=jsonb_set(item,array[''result'',''reasons''],to_jsonb(codes));item:=jsonb_set(item,array[''result'',''decision''],to_jsonb(case when cardinality(codes)=0 then ''in_scope'' else ''review_required'' end));item:=item||jsonb_build_object(''status'',case when cardinality(codes)=0 then ''resolved'' else ''open'' end,''version'',encode(sha256(convert_to(jsonb_build_array(item->>''version'',to_jsonb(c))::text,''UTF8'')),''hex''));return item||jsonb_build_object(''residenceReview'',jsonb_build_object(''confirmed'',not (item->''result''->''reasons'') ? ''online_residence_unknown'' and item->''facts''->>''delivery_mode''=''online'' and (machimoa_review.myseoul_residence_confirmed(item->''facts'') or item->''facts''->>''residence_scope'' in (''nationwide'',''includes_capital'',''capital'') and item->''facts''->''residence_evidence''<>''[]''::jsonb), ''basis'',case when machimoa_review.myseoul_residence_confirmed(item->''facts'') then ''operator_no_restriction'' when item->''facts''->>''residence_scope'' in (''nationwide'',''includes_capital'',''capital'') and item->''facts''->''residence_evidence''<>''[]''::jsonb then ''source_evidence'' else ''unconfirmed'' end));end\n$function$\n", "machimoa_review.myseoul_reason_fields(text)": "CREATE OR REPLACE FUNCTION machimoa_review.myseoul_reason_fields(reason text)\n RETURNS text[]\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\n select case when reason in (''source_change_conflict:application'',''source_change_conflict:operation'') then array[''periods''] when reason like ''source_change_conflict:%'' and split_part(reason,'':'',2) in (''description'',''official_url'',''public_category'',''purpose'',''target'',''residence'',''age'',''companion'',''language'',''conditions'',''application_actor'',''venue'',''delivery_mode'',''activity_region'',''activity_evidence'',''residence_scope'',''residence_evidence'',''qualification_note'',''fees'',''periods'',''session_evidence'',''meeting_evidence'',''application_methods'',''application_links'',''source_status'') then array[split_part(reason,'':'',2)]\n when reason=''description_missing'' then array[''description'']\n when reason=''target_missing'' then array[''target'',''conditions'',''application_actor'']\n when reason=''application_actor_unknown'' then array[''application_actor'',''target'',''conditions'']\n when reason in (''delivery_mode_unknown'',''course_modes_unresolved'',''activity_region_unknown'') then array[''delivery_mode'',''activity_region'',''venue'',''activity_evidence'']\n when reason=''online_residence_unknown'' then array[''residence_scope'',''residence'',''residence_evidence'']\n when reason=''category_unresolved'' then array[''public_category'',''purpose'']\n when reason=''nationality_or_visa_unresolved'' then array[''qualification_note'']\n when reason in (''application_period_unknown'',''operation_period_unknown'') then array[''periods'',''session_evidence'']\n when reason=''application_method_missing'' then array[''application_methods'',''application_links'']\n when reason in (''fee_unknown'',''fee_components_unresolved'') then array[''fees'']\n when reason=''application_state_unknown'' then array[''source_status'',''periods'']\n when reason=''source_fact_conflict:application_method'' then array[''application_methods'',''application_links'']\n when reason in (''source_fact_conflict:application'',''source_fact_conflict:operation'') then array[''periods'',''session_evidence'']\n when reason=''source_fact_conflict:target'' then array[''target'',''conditions'']\n when reason=''source_fact_conflict:mode'' then array[''delivery_mode'',''activity_evidence'']\n when reason=''source_fact_conflict:venue'' then array[''venue'',''activity_region'',''activity_evidence'']\n when reason=''source_fact_conflict:status'' then array[''source_status'',''periods'']\n when reason in (''source_fact_conflict:tuition'',''source_fact_conflict:admission'',''source_fact_conflict:materials'',''source_fact_conflict:extra_fee'') then array[''fees'']\n else ''{}''::text[] end\n$function$\n"}'::jsonb);
create table machimoa_review.myseoul_review_confirmations(
 event_id bigint primary key references machimoa_review.admin_review_events(id) on delete restrict,
 source_item_id uuid not null references machimoa_review.source_items(id) on delete restrict,
 revision_hash text not null check(revision_hash ~ '^[a-f0-9]{64}$'),
 kind text not null check(kind in ('activity','body')),
 confirmed_values jsonb not null check(jsonb_typeof(confirmed_values)='object'),
 source_reference jsonb not null check(jsonb_typeof(source_reference)='object')
);
alter table machimoa_review.myseoul_review_confirmations enable row level security;
revoke all on machimoa_review.myseoul_review_confirmations from public,anon,authenticated,service_role;
create function machimoa_review.myseoul_region_confirmed(f jsonb) returns boolean
language sql stable set search_path='' as $$
 select exists(select 1 from machimoa_review.myseoul_review_confirmations r
 join machimoa_review.source_items s on s.id=r.source_item_id and s.revision_hash=r.revision_hash and s.source_id='myseoul_program'
 join machimoa_review.source_item_content_filters cf on cf.source_item_id=s.id and cf.revision_hash=s.revision_hash
 where r.kind='activity' and r.revision_hash=f->>'source_revision'
 and s.normalized_payload->>'official_url'=f->>'official_url'
 and r.confirmed_values->'delivery_mode'=f->'delivery_mode'
 and r.confirmed_values->'activity_region'=f->'activity_region'
 and r.confirmed_values->'location'=cf.data->'location'
 and (cf.data->>'category'='event' or cf.data->'delivery'->>'value'=case f->>'delivery_mode' when 'offline' then 'onsite' when 'mixed' then 'mixed' end));
$$;
create function machimoa_review.myseoul_body_confirmed(f jsonb) returns boolean
language sql stable set search_path='' as $$
 select exists(select 1 from machimoa_review.myseoul_review_confirmations r
 join machimoa_review.source_items s on s.id=r.source_item_id and s.revision_hash=r.revision_hash and s.source_id='myseoul_program'
 where r.kind='body' and r.revision_hash=f->>'source_revision'
 and s.normalized_payload->>'official_url'=f->>'official_url'
 and r.confirmed_values->'description'=f->'description'
 and s.normalized_payload->'source_image_url'=r.source_reference->'imageUrl'
 and char_length(btrim(f->>'description'))>=20);
$$;
create function machimoa_review.myseoul_review_body_ready(p_id uuid,p_revision text) returns boolean
language sql stable set search_path='' as $$
 select coalesce((select s.body_usable or machimoa_review.myseoul_body_confirmed(p.facts)
 from machimoa_review.source_items s join machimoa_review.source_item_program_facts p on p.source_item_id=s.id and p.revision_hash=s.revision_hash
 where s.id=p_id and s.revision_hash=p_revision and s.source_id='myseoul_program'),false);
$$;

-- Explicit activity confirmation and public filters are one transaction.
create function public.admin_myseoul_activity_confirm(p_id uuid,p_revision text,p_version text,p_filter_version bigint,p_filters jsonb,p_patch jsonb,p_actor uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item jsonb;f jsonb;cf machimoa_review.source_item_content_filters%rowtype;d jsonb;mode text;ev bigint;fields text[];before_f jsonb;
begin
 item:=machimoa_review.myseoul_admin_lock(p_id,p_revision,p_version,p_actor);
 if machimoa_review.classification_publication(p_id) is not null or exists(select 1 from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=p_revision) then raise sqlstate 'PT409' using message='myseoul_confirmation_boundary';end if;
 if not (item->'result'->'reasons') ? 'activity_region_unknown' and not (item->'result'->'reasons') ? 'delivery_mode_unknown' then raise sqlstate 'PT409' using message='myseoul_confirmation_not_pending';end if;
 if p_patch is null or jsonb_typeof(p_patch)<>'object' or p_patch ?| array['activity_region','venue','activity_evidence','delivery_mode','public_category','purpose'] then raise sqlstate 'PT422' using message='invalid_myseoul_confirmation';end if;
 select * into cf from machimoa_review.source_item_content_filters where source_item_id=p_id and revision_hash=p_revision for update;
 if not found or cf.filter_version is distinct from p_filter_version then raise sqlstate 'PT409' using message='content_filter_input_changed';end if;
 if p_patch<>'{}'::jsonb then
 item:=public.admin_myseoul_program_save_v2(p_id,p_revision,p_version,p_patch,p_actor);
 select * into cf from machimoa_review.source_item_content_filters where source_item_id=p_id and revision_hash=p_revision;
 end if;
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or octet_length(p_filters::text)>120000 or not p_filters ? 'location' or exists(select 1 from jsonb_object_keys(p_filters) key where key not in ('topic','location','delivery','audience','spaceKind','application','schedule')) then raise sqlstate 'PT422' using message='invalid_content_filters';end if;
 d:=cf.data||p_filters;perform machimoa_review.content_filter_validate(d);
 if d->>'category' not in ('program','event') or d->>'category' is distinct from machimoa_review.content_filter_category(p_id,p_revision) then raise sqlstate 'PT422' using message='content_filter_category_changed';end if;
 if d->'location'->>'status'<>'known' or d->'location'->'value'->>'scope'<>'specific' or jsonb_array_length(d->'location'->'value'->'venues')=0 or exists(select 1 from jsonb_array_elements(d->'location'->'value'->'venues') v where v->>'province' not in ('11','28','41')) then raise sqlstate 'PT422' using message='myseoul_confirmation_capital_required';end if;
 f:=item->'facts';before_f:=f;
 mode:=case when d->>'category'='event' then f->>'delivery_mode' when d->'delivery'->>'status'='known' then case d->'delivery'->>'value' when 'onsite' then 'offline' when 'mixed' then 'mixed' else 'online' end else 'unknown' end;
 if mode not in ('offline','mixed') or f->>'activity_region'='noncapital' or f->'scope_exclusions'<>'[]'::jsonb then raise sqlstate 'PT422' using message='myseoul_confirmation_capital_required';end if;
 if mode is distinct from f->>'delivery_mode' and not (item->'editableFields') ? 'delivery_mode' then raise sqlstate 'PT422' using message='myseoul_field_read_only';end if;
 f:=jsonb_set(jsonb_set(f,'{delivery_mode}',to_jsonb(mode)),'{activity_region}','"capital"');
 f:=jsonb_set(f,'{issues}',coalesce((select jsonb_agg(value) from jsonb_array_elements(f->'issues') where value->>'code' not in ('activity_region_unknown','delivery_mode_unknown')),'[]'));
 perform machimoa_review.myseoul_validate(f);
 update machimoa_review.source_item_program_facts set facts=f,facts_version=facts_version+1,updated_by=p_actor,updated_at=clock_timestamp() where source_item_id=p_id and revision_hash=p_revision;
 if not machimoa_review.content_filter_consistent(p_id,p_revision,d) then raise sqlstate 'PT422' using message='content_filter_facts_mismatch';end if;
 select array_agg(key order by key) into fields from jsonb_object_keys(p_filters) key;
 update machimoa_review.source_item_content_filters set data=d,filter_version=filter_version+1,source_binding=machimoa_review.content_filter_binding(p_id,p_revision),origins=origins||(select jsonb_object_agg(k,'operator') from unnest(fields) k),updated_at=clock_timestamp() where source_item_id=p_id and revision_hash=p_revision;
 insert into machimoa_review.content_filter_edits(source_item_id,revision_hash,filter_version,actor,origin,fields,before_data,after_data) select p_id,p_revision,filter_version,p_actor,'operator',fields,cf.data,d from machimoa_review.source_item_content_filters where source_item_id=p_id and revision_hash=p_revision;
 insert into machimoa_review.admin_review_events(source_item_id,revision_hash,action,actor,note,changed_fields) values(p_id,p_revision,'save_facts',p_actor,'원문 대조 후 개최 지역 확인',array['delivery_mode','activity_region','confirmed:activity_region']) returning id into ev;
 insert into machimoa_review.myseoul_fact_edits(event_id,before_patch,after_patch,activity_confirmed) values(ev,jsonb_build_object('delivery_mode',before_f->'delivery_mode','activity_region',before_f->'activity_region'),jsonb_build_object('delivery_mode',f->'delivery_mode','activity_region',f->'activity_region'),false);
 insert into machimoa_review.myseoul_review_confirmations values(ev,p_id,p_revision,'activity',jsonb_build_object('delivery_mode',f->'delivery_mode','activity_region',f->'activity_region','location',d->'location'),jsonb_build_object('officialUrl',f->'official_url'));
 perform machimoa_review.myseoul_refresh(p_id);
 return public.admin_myseoul_program_detail(p_id);
end $$;

create function public.admin_myseoul_body_confirm(p_id uuid,p_revision text,p_version text,p_description text,p_actor uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item jsonb;s machimoa_review.source_items%rowtype;c machimoa_review.review_classifications%rowtype;d jsonb;ev bigint;
begin
 item:=machimoa_review.myseoul_admin_lock(p_id,p_revision,p_version,p_actor);
 if machimoa_review.classification_publication(p_id) is not null then raise sqlstate 'PT409' using message='myseoul_confirmation_boundary';end if;
 select * into s from machimoa_review.source_items where id=p_id;
 select * into c from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=p_revision for update;
 if found and c.native_snapshot is distinct from machimoa_review.classification_native(p_id) then raise sqlstate 'PT409' using message='classification_input_changed';end if;
 if s.body_usable or not s.attachment_present or machimoa_review.safe_source_image_url(s.normalized_payload->>'source_image_url') is null or p_description is null or char_length(btrim(p_description)) not between 20 and 60000 or p_description ~ '[<>]' then raise sqlstate 'PT422' using message='invalid_myseoul_body_confirmation';end if;
 if not (item->'result'->'reasons') ? 'attachment_dependent' then raise sqlstate 'PT409' using message='myseoul_confirmation_not_pending';end if;
 -- A changed description uses the existing scoped facts/history contract.
 if item->'facts'->>'description' is distinct from btrim(p_description) then item:=public.admin_myseoul_program_save_v2(p_id,p_revision,p_version,jsonb_build_object('description',btrim(p_description)),p_actor);end if;
 insert into machimoa_review.admin_review_events(source_item_id,revision_hash,action,actor,note,changed_fields) values(p_id,p_revision,'save_facts',p_actor,'이미지 원문 확인 및 설명 보완',array['description','confirmed:attachment_dependent']) returning id into ev;
 insert into machimoa_review.myseoul_review_confirmations values(ev,p_id,p_revision,'body',jsonb_build_object('description',item->'facts'->'description'),jsonb_build_object('officialUrl',s.normalized_payload->'official_url','imageUrl',s.normalized_payload->'source_image_url'));
 perform machimoa_review.myseoul_refresh(p_id);
 if c.source_item_id is not null then
 d:=public.admin_review_classification_detail(p_id);
 perform public.admin_review_reclassify(p_id,p_revision,d->>'version',(d->>'classificationVersion')::bigint,c.facts,c.filters,'이미지 원문 확인 및 설명 보완 · 기존 분류와 필터 보존',p_actor);
 end if;
 return public.admin_myseoul_program_detail(p_id);
end $$;

revoke all on function machimoa_review.myseoul_region_confirmed(jsonb),machimoa_review.myseoul_body_confirmed(jsonb),machimoa_review.myseoul_review_body_ready(uuid,text) from public,anon,authenticated,service_role;
revoke all on function public.admin_myseoul_activity_confirm(uuid,text,text,bigint,jsonb,jsonb,uuid),public.admin_myseoul_body_confirm(uuid,text,text,text,uuid) from public,anon,authenticated,service_role;
grant execute on function public.admin_myseoul_activity_confirm(uuid,text,text,bigint,jsonb,jsonb,uuid),public.admin_myseoul_body_confirm(uuid,text,text,text,uuid) to service_role;

CREATE OR REPLACE FUNCTION machimoa_review.myseoul_evaluate(f jsonb, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare reasons text[]:=array(select value->>'code' from jsonb_array_elements(f->'issues'));
 exclusions text[]:=array(select jsonb_array_elements_text(f->'scope_exclusions')); app text:='unknown'; mode text:=f->>'delivery_mode';
 k text; p jsonb; app_period jsonb; op_period jsonb; endpoint jsonb; boundary timestamptz; decision text; quality text; scope text; status text;
begin
 perform machimoa_review.myseoul_validate(f);
 if p_now is null then raise exception using errcode='PT422',message='evaluation_time_required';end if;
 if f->>'application_actor'='institution_only' then exclusions:=array_append(exclusions,'institution_only');end if;
 if exists(select 1 from machimoa_review.source_items s where s.source_id='myseoul_program' and s.revision_hash=f->>'source_revision' and s.normalized_payload->>'official_url'=f->>'official_url' and not s.body_usable and s.attachment_present) and not machimoa_review.myseoul_body_confirmed(f) then reasons:=array_append(reasons,'attachment_dependent');end if;
 if char_length(btrim(f->>'description'))<20 then reasons:=array_append(reasons,'description_missing');end if;
 if btrim(f->>'target')='' then reasons:=array_append(reasons,'target_missing');end if;
 if f->>'application_actor'='unknown' then reasons:=array_append(reasons,'application_actor_unknown');end if;
 if f->>'public_category'='unknown' then reasons:=array_append(reasons,'category_unresolved');end if;
 if mode in ('unknown','course_unresolved') then reasons:=array_append(reasons,case when mode='unknown' then 'delivery_mode_unknown' else 'course_modes_unresolved' end);end if;
 if mode in ('offline','mixed') then
 if f->>'activity_region'='noncapital' then exclusions:=array_append(exclusions,'noncapital_venue');
 elsif (f->>'activity_region'<>'capital' or (f->'activity_evidence'='[]'::jsonb and not machimoa_review.myseoul_activity_confirmed(f)) or btrim(f->>'venue')='') and not machimoa_review.myseoul_region_confirmed(f) then reasons:=array_append(reasons,'activity_region_unknown');end if;end if;
 if mode='online' then
 if f->>'residence_scope'='noncapital_only' then exclusions:=array_append(exclusions,'online_noncapital_only');
 elsif (f->>'residence_scope' not in ('nationwide','includes_capital','capital') or f->'residence_evidence'='[]'::jsonb) and not machimoa_review.myseoul_residence_confirmed(f) then reasons:=array_append(reasons,'online_residence_unknown');end if;end if;
 if f->'application_methods'='[]'::jsonb then reasons:=array_append(reasons,'application_method_missing');end if;
 if f->'fees'='[]'::jsonb or exists(select 1 from jsonb_array_elements(f->'fees') fee cross join lateral jsonb_array_elements_text(fee->'evidence') v
 where v !~ '무료|[0-9][0-9,]*[[:space:]]*원|별도[[:space:]]*(부담|납부)') then reasons:=array_append(reasons,'fee_unknown');end if;
 for k in select fee->>'component' from jsonb_array_elements(f->'fees') fee cross join lateral jsonb_array_elements_text(fee->'evidence') v
 group by fee->>'component' having count(distinct machimoa_review.myseoul_comparison(fee->>'component',v))>1 loop
 reasons:=array_append(reasons,'source_fact_conflict:'||k);end loop;
 foreach k in array array['application','operation'] loop
 if exists(select 1 from jsonb_array_elements(f->'periods'->k) v where v->>'status'<>'ok') or k='operation' and not exists(
 select 1 from jsonb_array_elements(f->'periods'->k) v where v->>'status'='ok') then reasons:=array_append(reasons,k||'_period_unknown');end if;
 if (select count(distinct v->'endpoints') from jsonb_array_elements(f->'periods'->k) v where v->>'status'='ok')>1 then reasons:=array_append(reasons,'source_fact_conflict:'||k);end if;end loop;
 if (select count(distinct machimoa_review.myseoul_comparison('status',v)) from jsonb_array_elements_text(f->'source_status') v)>1 then reasons:=array_append(reasons,'source_fact_conflict:status');end if;
 select value into app_period from jsonb_array_elements(f->'periods'->'application') where value->>'status'='ok' limit 1;
 select value into op_period from jsonb_array_elements(f->'periods'->'operation') where value->>'status'='ok' limit 1;
 status:=array_to_string(array(select jsonb_array_elements_text(f->'source_status')),E'\n');
 if status ~ '접수[[:space:]]*종료|모집[[:space:]]*종료|예약[[:space:]]*마감|접수[[:space:]]*마감|신청[[:space:]]*(마감|종료)' then app:='closed';
 elsif app_period is not null then
 endpoint:=app_period->'endpoints'->(jsonb_array_length(app_period->'endpoints')-1);
 boundary:=machimoa_review.myseoul_boundary(endpoint,true);
 app:=case when p_now<machimoa_review.myseoul_boundary(app_period->'endpoints'->0,false) then 'not_started'
 when endpoint->>'precision'='day' and p_now>=boundary or endpoint->>'precision'='minute' and p_now>boundary then 'closed' else 'open' end;
 elsif status ~ '접수[[:space:]]*중|모집[[:space:]]*중|신청[[:space:]]*중|추가[[:space:]]*모집|현장[[:space:]]*접수' then app:='open';
 else reasons:=array_append(reasons,'application_period_unknown');end if;
 if op_period is not null then endpoint:=op_period->'endpoints'->(jsonb_array_length(op_period->'endpoints')-1);
 boundary:=machimoa_review.myseoul_boundary(endpoint,true);
 if endpoint->>'precision'='day' and p_now>=boundary or endpoint->>'precision'='minute' and p_now>boundary then app:='ended';end if;end if;
 if reasons && array['source_fact_conflict:application','source_fact_conflict:operation','source_fact_conflict:status'] then app:='unknown';end if;
 if app='unknown' then reasons:=array_append(reasons,'application_state_unknown');end if;
 select coalesce(array_agg(code order by ord),'{}') into reasons from (select code,min(ord) ord from unnest(reasons) with ordinality q(code,ord) group by code) q;
 select coalesce(array_agg(code order by ord),'{}') into exclusions from (select code,min(ord) ord from unnest(exclusions) with ordinality q(code,ord) group by code) q;
 scope:=case when cardinality(exclusions)>0 then 'excluded' when reasons && array['target_missing','application_actor_unknown','delivery_mode_unknown',
 'course_modes_unresolved','activity_region_unknown','online_residence_unknown','category_unresolved','nationality_or_visa_unresolved'] then 'unknown' else 'included' end;
 quality:=case when exists(select 1 from unnest(reasons) r where r like 'source_fact_conflict:%' or r like 'source_change_conflict:%') then 'conflict' when cardinality(reasons)>0 then 'insufficient' else 'sufficient' end;
 decision:=case when cardinality(exclusions)>0 then 'out_of_scope' when cardinality(reasons)>0 then 'review_required' when app='open' then 'in_scope' else 'not_currently_available' end;
 reasons:=exclusions||reasons;
 if app in ('closed','not_started','ended') then reasons:=array_append(reasons,case when app='ended' then 'operation_ended' else 'application_'||app end);end if;
 select coalesce(array_agg(code order by ord),'{}') into reasons from (select code,min(ord) ord from unnest(reasons) with ordinality q(code,ord) group by code) q;
 return jsonb_build_object('decision',decision,'disposition',case when cardinality(exclusions)>0 then 'non_target' when decision='in_scope' then 'target' else 'observe_only' end,
 'scope',scope,'application',app,'quality',quality,'public_category',f->>'public_category','reasons',to_jsonb(reasons),'ai_status','blocked');
end $function$
;

CREATE OR REPLACE FUNCTION machimoa_review.classification_reasons(p_id uuid, f jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s machimoa_review.source_items%rowtype;pf machimoa_review.source_item_program_facts%rowtype;r jsonb;codes text[];g jsonb;d jsonb;venue_mode boolean;venue_ready boolean:=false;
begin
 select * into s from machimoa_review.source_items where id=p_id;
 select * into pf from machimoa_review.source_item_program_facts where source_item_id=p_id and revision_hash=s.revision_hash;
 if pf.source_item_id is not null then
 r:=case when s.source_id='myseoul_program' then machimoa_review.myseoul_evaluate(pf.facts,statement_timestamp()) else machimoa_review.program_evaluate(pf.facts,statement_timestamp()) end;
 if pf.manual_excluded or r->>'decision'='out_of_scope' then return array['classification_source_excluded'];end if;
 select array(select code from jsonb_array_elements_text(coalesce(r->'reasons','[]')) code where not (machimoa_review.publication_temporal_ready(r) and code in ('application_not_started','application_closed','operation_ended','not_currently_accepting','program_ended')) and code not in
 ('category_unresolved','delivery_mode_unknown','activity_region_unknown','application_period_unknown','operation_period_unknown','application_state_unknown','online_residence_unknown') and code not like 'content_filter:%') into codes;
 else codes:='{}';end if;
 if f->>'productType' not in ('event_program','policy_reference','living_guide') then return array_append(codes,'classification_missing_facts');end if;
 select to_jsonb(gate) into g from machimoa_review.evaluate_source_item_gates(s.body_usable or machimoa_review.myseoul_review_body_ready(p_id,s.revision_hash),s.has_source_url,s.attachment_present,f->>'productType','{}',machimoa_review.classification_gate(f)) gate;
 select filters into d from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=s.revision_hash;
 if (d is null or d->>'category' is distinct from f->>'category') and f->>'category' in ('program','event','youth_space') then d:=machimoa_review.classification_draft(p_id,f->>'category')->'filters';end if;
 venue_mode:=f->>'productType'='event_program' and f->>'category' in ('program','event','youth_space') and f->>'delivery' in ('offline','hybrid') and (f->>'category'<>'youth_space' or d->'spaceKind'->>'value' is distinct from 'news');
 if venue_mode then
 select filters into d from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=s.revision_hash;
 if d is null or d->>'category' is distinct from f->>'category' then d:=machimoa_review.classification_draft(p_id,f->>'category')->'filters';end if;
 venue_ready:=d->'location'->>'status'='known' and (d->'location'->'value'->>'scope'='nationwide' or d->'location'->'value'->>'scope'='specific' and jsonb_array_length(d->'location'->'value'->'venues')>0 and not exists(select 1 from jsonb_array_elements(d->'location'->'value'->'venues') x where x->>'province' not in ('11','28','41')));
 if coalesce(venue_ready,false) is not true then codes:=array_append(codes,'activity_region_unknown');end if;
 end if;
 codes:=codes||array(select code from jsonb_array_elements(coalesce(g->'jobs','[]')) job cross join lateral jsonb_array_elements_text(job->'reason_codes') code where not (venue_mode and coalesce(venue_ready,false) and code='region_scope_unknown'));
 if g->>'disposition'<>'target' and cardinality(codes)=0 and not (venue_mode and coalesce(venue_ready,false) and g->>'disposition'='region_review_required' and g->>'region_status'='review_required' and g->>'audience_status'='not_applicable') then codes:=array_append(codes,'classification_scope_unresolved');end if;
 return array(select distinct c from unnest(codes) c);
end $function$
;

CREATE OR REPLACE FUNCTION public.admin_myseoul_program_detail(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb;c machimoa_review.review_classifications%rowtype;codes text[];begin item:=machimoa_review.cl_base_pub_admin_myseoul_program_detail(p_id);select * into c from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=item->>'revision';if not found then return item||jsonb_build_object('activityReview',jsonb_build_object('confirmed',machimoa_review.myseoul_region_confirmed(item->'facts')),'bodyReview',jsonb_build_object('required',not (select body_usable from machimoa_review.source_items where id=p_id) and (select attachment_present from machimoa_review.source_items where id=p_id),'confirmed',machimoa_review.myseoul_body_confirmed(item->'facts'),'imageUrl',machimoa_review.safe_source_image_url((select normalized_payload->>'source_image_url' from machimoa_review.source_items where id=p_id))))||jsonb_build_object('residenceReview',jsonb_build_object('confirmed',not (item->'result'->'reasons') ? 'online_residence_unknown' and item->'facts'->>'delivery_mode'='online' and (machimoa_review.myseoul_residence_confirmed(item->'facts') or item->'facts'->>'residence_scope' in ('nationwide','includes_capital','capital') and item->'facts'->'residence_evidence'<>'[]'::jsonb), 'basis',case when machimoa_review.myseoul_residence_confirmed(item->'facts') then 'operator_no_restriction' when item->'facts'->>'residence_scope' in ('nationwide','includes_capital','capital') and item->'facts'->'residence_evidence'<>'[]'::jsonb then 'source_evidence' else 'unconfirmed' end));end if;codes:=array(select distinct code from unnest(machimoa_review.classification_reasons(p_id,c.facts)||array(select unnest(j.reason_codes) from machimoa_review.processing_jobs j where j.source_item_id=p_id and j.revision_hash=c.revision_hash and j.processing_stage<>'ai_enrichment' and j.status in ('queued','claimed'))) code);if c.native_snapshot is distinct from machimoa_review.classification_native(p_id) then codes:=array_append(codes,'classification_input_changed');end if;item:=jsonb_set(item,array['result','reasons'],to_jsonb(codes));item:=jsonb_set(item,array['result','decision'],to_jsonb(case when cardinality(codes)=0 then 'in_scope' else 'review_required' end));item:=item||jsonb_build_object('status',case when cardinality(codes)=0 then 'resolved' else 'open' end,'version',encode(sha256(convert_to(jsonb_build_array(item->>'version',to_jsonb(c))::text,'UTF8')),'hex'));return item||jsonb_build_object('activityReview',jsonb_build_object('confirmed',machimoa_review.myseoul_region_confirmed(item->'facts')),'bodyReview',jsonb_build_object('required',not (select body_usable from machimoa_review.source_items where id=p_id) and (select attachment_present from machimoa_review.source_items where id=p_id),'confirmed',machimoa_review.myseoul_body_confirmed(item->'facts'),'imageUrl',machimoa_review.safe_source_image_url((select normalized_payload->>'source_image_url' from machimoa_review.source_items where id=p_id))))||jsonb_build_object('residenceReview',jsonb_build_object('confirmed',not (item->'result'->'reasons') ? 'online_residence_unknown' and item->'facts'->>'delivery_mode'='online' and (machimoa_review.myseoul_residence_confirmed(item->'facts') or item->'facts'->>'residence_scope' in ('nationwide','includes_capital','capital') and item->'facts'->'residence_evidence'<>'[]'::jsonb), 'basis',case when machimoa_review.myseoul_residence_confirmed(item->'facts') then 'operator_no_restriction' when item->'facts'->>'residence_scope' in ('nationwide','includes_capital','capital') and item->'facts'->'residence_evidence'<>'[]'::jsonb then 'source_evidence' else 'unconfirmed' end));end
$function$
;

CREATE OR REPLACE FUNCTION machimoa_review.myseoul_reason_fields(reason text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select case when reason in ('source_change_conflict:application','source_change_conflict:operation') then array['periods'] when reason like 'source_change_conflict:%' and split_part(reason,':',2) in ('description','official_url','public_category','purpose','target','residence','age','companion','language','conditions','application_actor','venue','delivery_mode','activity_region','activity_evidence','residence_scope','residence_evidence','qualification_note','fees','periods','session_evidence','meeting_evidence','application_methods','application_links','source_status') then array[split_part(reason,':',2)]
 when reason in ('description_missing','attachment_dependent') then array['description']
 when reason='target_missing' then array['target','conditions','application_actor']
 when reason='application_actor_unknown' then array['application_actor','target','conditions']
 when reason in ('delivery_mode_unknown','course_modes_unresolved','activity_region_unknown') then array['delivery_mode','activity_region','venue','activity_evidence']
 when reason='online_residence_unknown' then array['residence_scope','residence','residence_evidence']
 when reason='category_unresolved' then array['public_category','purpose']
 when reason='nationality_or_visa_unresolved' then array['qualification_note']
 when reason in ('application_period_unknown','operation_period_unknown') then array['periods','session_evidence']
 when reason='application_method_missing' then array['application_methods','application_links']
 when reason in ('fee_unknown','fee_components_unresolved') then array['fees']
 when reason='application_state_unknown' then array['source_status','periods']
 when reason='source_fact_conflict:application_method' then array['application_methods','application_links']
 when reason in ('source_fact_conflict:application','source_fact_conflict:operation') then array['periods','session_evidence']
 when reason='source_fact_conflict:target' then array['target','conditions']
 when reason='source_fact_conflict:mode' then array['delivery_mode','activity_evidence']
 when reason='source_fact_conflict:venue' then array['venue','activity_region','activity_evidence']
 when reason='source_fact_conflict:status' then array['source_status','periods']
 when reason in ('source_fact_conflict:tuition','source_fact_conflict:admission','source_fact_conflict:materials','source_fact_conflict:extra_fee') then array['fees']
 else '{}'::text[] end
$function$
;
create function machimoa_review.myseoul_confirmation_dirty() returns trigger language plpgsql set search_path='' as $$begin update machimoa_review.myseoul_confirmation_install set dirty=true where singleton;return null;end $$;
revoke all on function machimoa_review.myseoul_confirmation_dirty() from public,anon,authenticated,service_role;
create trigger myseoul_confirmation_dirty after insert or update or delete on machimoa_review.source_item_program_facts for each statement execute function machimoa_review.myseoul_confirmation_dirty();
create trigger myseoul_confirmation_dirty after insert or update or delete on machimoa_review.source_item_content_filters for each statement execute function machimoa_review.myseoul_confirmation_dirty();
create trigger myseoul_confirmation_dirty after insert or update or delete on machimoa_review.review_classifications for each statement execute function machimoa_review.myseoul_confirmation_dirty();
create trigger myseoul_confirmation_dirty after insert or update or delete on machimoa_review.review_classification_history for each statement execute function machimoa_review.myseoul_confirmation_dirty();
create trigger myseoul_confirmation_dirty after insert or update or delete on machimoa_review.myseoul_review_confirmations for each statement execute function machimoa_review.myseoul_confirmation_dirty();
commit;
